code_snippets.parse_list:
def parse(self, response):
    for li in response.css('ul li'):
        detail_url = li.css('a::attr(href)').get()
        title = li.css('a::text').get()
        if detail_url and detail_url.startswith('http://www.hhs.gov/'):
            yield response.follow(detail_url, self.parse_detail, meta={'title': title})

code_snippets.parse_detail:
def parse_detail(self, response):
    title = response.meta.get('title')
    # 示例：抓取PDF链接
    pdf_links = response.css('a[href$=".pdf"]::attr(href)').getall()
    yield {
        'title': title,
        'pdf_links': pdf_links,
        'detail_url': response.url
    }
